import zlib
import base64

b = ""

try:
    # Proses pembongkaran lapisan secara terbalik
    d = base64.b64decode(b)
    r1 = bytearray(byte ^ 0x5C for byte in d)
    
    chacha_state = 0x6e617078
    salsa_state = 0x61707865
    r2 = bytearray()
    for i, byte in enumerate(r1):
        k_chacha = (chacha_state >> ((i % 4) * 8)) & 0xFF
        k_salsa = (salsa_state >> ((i % 4) * 8)) & 0xFF
        r2.append(byte ^ k_chacha ^ k_salsa)
        
    original_code = zlib.decompress(r2).decode('utf-8')
    exec(compile(original_code, '<string>', 'exec'))
except Exception as e:
    print(f"Gagal membongkar lapisan enkripsi: {e}")
